const sandLizardSheet=new Image();sandLizardSheet.assetSrc='assets/desert-sand-lizard-v1.png';
function beginSandLizard(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'sandBiteTail',bespoke:true,windup:.8,origin:{x:e.x,y:e.y},waves:0,angle:Math.atan2(p.y-e.y,p.x-e.x)};let dx=p.x-e.x,dy=p.y-e.y;e.facing=dx-dy<0?-1:1;}
function sandLizardBandContains(origin,index,point,angle=0){let radius=dist(origin,point),delta=Math.atan2(point.y-origin.y,point.x-origin.x)-angle;delta=Math.atan2(Math.sin(delta),Math.cos(delta));return index===0?radius<=125+1e-8&&Math.abs(delta)<=Math.PI/4+1e-8:radius>35+1e-8&&radius<=180+1e-8&&Math.abs(delta)>Math.PI/4+1e-8;}
const sandLizardAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{if(e.species!=='r4e5')return sandLizardAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);
 if(e.attack?.pattern!=='sandBiteTail'){e.t-=dt;e.nav=(e.nav||0)-dt;let distance=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&distance<=185&&clear)beginSandLizard(e);else{e.state='idle';if(distance>800&&!e.aware)return;if(distance<=100&&clear)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,100*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}}
 let a=e.attack;if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.4;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;while(a.waves<2&&e.elapsed>=.8+a.waves*.8){let index=a.waves++;e.struck=true;if(sandLizardBandContains(a.origin,index,p,a.angle)&&lineClear(a.origin,p))hurt(index===0?48:58);playSound('impact',a.origin.x,a.origin.y);}
 if(e.elapsed>=2.4){e.attack=null;e.state='idle';e.t=2.5;}
};
const sandLizardDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r4e5'||!sandLizardSheet.complete||!sandLizardSheet.naturalWidth||!sandLizardSheet.naturalHeight)return sandLizardDrawBase(e,size);let f=spriteFrame(e.hp<=0?'idle':e.state,e.hp<=0?0:e.anim);if(e.hp>0&&e.attack?.pattern==='sandBiteTail')f={row:2,col:e.elapsed<.4?0:e.elapsed<.8?1:e.elapsed<1.6?2:3};let q=project(e.x,e.y),sw=sandLizardSheet.naturalWidth/4,sh=sandLizardSheet.naturalHeight/3,w=165,h=w*sh/sw;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';let anchor=f.row===0?.82:f.row===1?.78:.79;if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,sandLizardSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(sandLizardSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const sandLizardSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r4e5'?100:sandLizardSizeBase(e);
function paintSandLizardBand(a,index,fired){let q=project(a.origin.x,a.origin.y),inner=index?35:0,outer=index?180:125,start=a.angle+(index?Math.PI/4:-Math.PI/4),end=a.angle+(index?Math.PI*7/4:Math.PI/4);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.fillStyle=fired?'#ffdb9c66':index?'#d5a0eb25':'#e6a96524';ctx.strokeStyle=fired?'#fff1ce':index?'#d3a4ee':'#e9bc78';ctx.lineWidth=fired?3:2;ctx.beginPath();ctx.arc(0,0,outer,start,end);if(inner){ctx.lineTo(Math.cos(end)*inner,Math.sin(end)*inner);ctx.arc(0,0,inner,end,start,true);}else ctx.lineTo(0,0);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}
const sandLizardGroundBase=drawGroundEffects;drawGroundEffects=()=>{sandLizardGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r4e5'):enemies)){let a=e.attack;if(e.species!=='r4e5'||e.hp<=0||a?.pattern!=='sandBiteTail'||!visibleAt(a.origin.x,a.origin.y))continue;if(a.waves<2)paintSandLizardBand(a,a.waves,false);if(a.waves>0&&e.elapsed<.8+(a.waves-1)*.8+.18)paintSandLizardBand(a,a.waves-1,true);}};
